void streamReplyWithCGLag(client *c, stream *s, streamCG *cg) {
    int valid = 0;
    long long lag = 0;

    if (!s->entries_added) {
        /* The lag of a newly-initialized stream is 0. */
        lag = 0;
        valid = 1;
    } else if (cg->entries_read != SCG_INVALID_ENTRIES_READ &&
               (streamIDEqZero(&s->max_deleted_entry_id) ||
                streamCompareID(&s->max_deleted_entry_id,&cg->last_id) <= 0))
    {
        /* No tombstone was added after the group's last-delivered-id, meaning
         * that entries_added - entries_read correctly reflects the number of
         * entries that are yet to be delivered. */
        lag = (long long)s->entries_added - cg->entries_read;
        valid = 1;
    } else if (cg->entries_read == SCG_INVALID_ENTRIES_READ) {
        /* The group's counter is invalid. Attempt to retrieve the group's
         * last ID logical read counter. */
        long long entries_read = streamEstimateDistanceFromFirstEverEntry(&cg->last_id,s);
        if (entries_read != SCG_INVALID_ENTRIES_READ) {
            /* A valid counter was obtained. */
            lag = (long long)s->entries_added - entries_read;
            valid = 1;
        }
        /* Otherwise, the lag isn't available: entries were added after the
         * group's last-delivered-id and later deleted, so neither the
         * group's counter nor an estimate can be trusted. */
    }

